/**
 * Display-only body orientation: the IAU WGCCRE rotation model with the
 * constants of NAIF pck00011.tpc (data/iau-rotation.json, generated by
 * scripts/gen-iau-rotation.py), including the periodic nutation/libration
 * terms the kernel lists (they matter for the Moon, Triton and Saturn's inner
 * moons). Pure; ordinary Math (this code never feeds the physics or replays).
 *
 * This is the same construction as src/mission/earth-orientation.ts
 * (R = Rz(90 deg + alpha0) * Rx(90 deg - delta0) * Rz(W), body-fixed -> ICRF),
 * reimplemented here because src/app may only reach src/mission through
 * mission-layer.ts, and that module uses the deterministic dmath functions
 * that the renderer does not need. Earth uses the plain IAU W (linear in TDB),
 * which is about 11 s of rotation (0.05 deg) off the true Earth rotation
 * angle: invisible at display scale.
 *
 * Body-fixed frame: x through the prime meridian, z along the IAU pole, so a
 * planetocentric east longitude lon and latitude lat is the direction
 * (cos lat cos lon, cos lat sin lon, sin lat).
 */
import data from './data/iau-rotation.json';

const DEG = Math.PI / 180;
const DAY = 86400;
const CENTURY = 36525 * DAY;

export interface NutTerm {
  /** Angle A = angle[0] + angle[1] T (+ angle[2] T^2), degrees. */
  readonly angle: readonly number[];
  readonly ra: number;
  readonly dec: number;
  readonly pm: number;
}

export interface IauRotation {
  readonly naifId: number;
  /** degrees, deg/century, deg/century^2 */
  readonly ra: readonly number[];
  readonly dec: readonly number[];
  /** degrees, deg/day, deg/day^2 */
  readonly pm: readonly number[];
  readonly nut?: readonly NutTerm[];
}

export const IAU_ROTATION: Readonly<Record<string, IauRotation>> = data.bodies as Record<string, IauRotation>;

export type Mat3 = Float64Array; // row-major

/** Pole right ascension, declination and prime meridian W (degrees) at TDB t (s from J2000). */
export function rotationAngles(m: IauRotation, t: number): { ra: number; dec: number; w: number } {
  const d = t / DAY;
  const T = t / CENTURY;
  let ra = m.ra[0] + m.ra[1] * T + (m.ra[2] ?? 0) * T * T;
  let dec = m.dec[0] + m.dec[1] * T + (m.dec[2] ?? 0) * T * T;
  // Reduce the large linear term modulo 360 before adding, to keep precision over centuries.
  const rate = m.pm[1] * d;
  let w = m.pm[0] + (rate - 360 * Math.floor(rate / 360)) + (m.pm[2] ?? 0) * d * d;
  if (m.nut) {
    for (const n of m.nut) {
      const a = (n.angle[0] + n.angle[1] * T + (n.angle[2] ?? 0) * T * T) * DEG;
      const s = Math.sin(a);
      ra += n.ra * s;
      dec += n.dec * Math.cos(a);
      w += n.pm * s;
    }
  }
  w -= 360 * Math.floor(w / 360);
  return { ra, dec, w };
}

/** Rotation body-fixed -> ICRF at t (row-major). */
export function bodyToIcrf(m: IauRotation, t: number, out: Mat3 = new Float64Array(9)): Mat3 {
  const { ra, dec, w } = rotationAngles(m, t);
  const a = (ra + 90) * DEG;
  const b = (90 - dec) * DEG;
  const c = w * DEG;
  const sa = Math.sin(a), ca = Math.cos(a);
  const sd = Math.sin(b), cd = Math.cos(b);
  const sw = Math.sin(c), cw = Math.cos(c);
  const a00 = ca, a01 = -sa * cd, a02 = sa * sd;
  const a10 = sa, a11 = ca * cd, a12 = -ca * sd;
  const a20 = 0, a21 = sd, a22 = cd;
  out[0] = a00 * cw + a01 * sw;
  out[1] = -a00 * sw + a01 * cw;
  out[2] = a02;
  out[3] = a10 * cw + a11 * sw;
  out[4] = -a10 * sw + a11 * cw;
  out[5] = a12;
  out[6] = a20 * cw + a21 * sw;
  out[7] = -a20 * sw + a21 * cw;
  out[8] = a22;
  return out;
}

/** out = a * b (row-major 3x3). */
export function mul3(a: ArrayLike<number>, b: ArrayLike<number>, out: Mat3 = new Float64Array(9)): Mat3 {
  for (let i = 0; i < 3; i++) {
    const r0 = a[3 * i], r1 = a[3 * i + 1], r2 = a[3 * i + 2];
    out[3 * i] = r0 * b[0] + r1 * b[3] + r2 * b[6];
    out[3 * i + 1] = r0 * b[1] + r1 * b[4] + r2 * b[7];
    out[3 * i + 2] = r0 * b[2] + r1 * b[5] + r2 * b[8];
  }
  return out;
}

/**
 * Planetocentric latitude and east longitude (degrees, lon in (-180, 180])
 * of the point on the body under an ICRF direction (e.g. toward the Sun).
 */
export function subPoint(m: IauRotation, t: number, dirIcrf: ArrayLike<number>): { lat: number; lon: number } {
  const r = bodyToIcrf(m, t);
  // body-fixed = R^T dir
  const x = r[0] * dirIcrf[0] + r[3] * dirIcrf[1] + r[6] * dirIcrf[2];
  const y = r[1] * dirIcrf[0] + r[4] * dirIcrf[1] + r[7] * dirIcrf[2];
  const z = r[2] * dirIcrf[0] + r[5] * dirIcrf[1] + r[8] * dirIcrf[2];
  return { lat: Math.atan2(z, Math.hypot(x, y)) / DEG, lon: Math.atan2(y, x) / DEG };
}
